"use strict";
function info(msg){console.log('[INFO] '+msg);}function warn(msg){console.log('[WARN] '+msg);}function error(msg){console.log('[ERROR] '+msg);} 
var roleHarvester = { run: function(creep){ try{ var source = creep.pos.findClosestByPath(FIND_SOURCES); if(!source) return; if(creep.store.getFreeCapacity()>0){ if(creep.harvest(source)===ERR_NOT_IN_RANGE){ creep.moveTo(source,{visualizePathStyle:{stroke:'#ffaa00'}}); } } else { var target = creep.pos.findClosestByPath(FIND_STRUCTURES, { filter: function(s){ return (s.structureType==STRUCTURE_SPAWN || s.structureType==STRUCTURE_EXTENSION) && s.store.getFreeCapacity(RESOURCE_ENERGY)>0; } }); if(target){ if(creep.transfer(target, RESOURCE_ENERGY)===ERR_NOT_IN_RANGE){ creep.moveTo(target,{visualizePathStyle:{stroke:'#ffffff'}}); } } } }catch(e){ console.log('harvester '+(creep.name||'')+' error: '+e);} } };
var roleBuilder = { run: function(creep){ try{ var target = creep.pos.findClosestByPath(FIND_CONSTRUCTION_SITES); if(!target) return; if(creep.build(target)===ERR_NOT_IN_RANGE){ creep.moveTo(target,{visualizePathStyle:{stroke:'#00ff00'}}); } }catch(e){ console.log('builder '+(creep.name||'')+' error: '+e);} } };
var roleUpgrader = { run: function(creep){ try{ var controller = (creep.room && creep.room.controller); if(!controller) return; if(creep.upgradeController(controller)===ERR_NOT_IN_RANGE){ creep.moveTo(controller,{visualizePathStyle:{stroke:'#ffffff'}}); } }catch(e){ console.log('upgrader '+(creep.name||'')+' error: '+e);} } };
function loop(){ try{ var cpuUsed = (Game && Game.cpu && Game.cpu.getUsed ? Game.cpu.getUsed() : 0); if(cpuUsed && cpuUsed>45){ info('High CPU usage detected: '+cpuUsed+', skipping heavy tasks this tick.'); return; } for(var name in Game.creeps){ var creep = Game.creeps[name]; try{ var role = (creep.memory && creep.memory.role) || 'harvester'; switch(role){ case 'harvester': roleHarvester.run(creep); break; case 'builder': roleBuilder.run(creep); break; case 'upgrader': roleUpgrader.run(creep); break; default: roleHarvester.run(creep); break; } } catch(e){ error('Error running creep '+name+': '+e); var mem = Memory; if(!mem.errors) mem.errors={}; mem.errors[name] = (mem.errors[name] || 0) + 1; } } } catch(e){ console.log('Top-level loop error: '+e);} }
if (typeof global !== 'undefined') { global.loop = loop; } else if (typeof window !== 'undefined') { window.loop = loop; }
module.exports = { loop: loop };